</head>
<body>
    <h1>🔨 打地鼠</h1>
    <div class="info-panel">
        <span>得分: <strong id="score">0</strong></span>
        <span>时间: <strong id="time">30</strong> 秒</span>
        <span>最高: <strong id="highScore">0</strong></span>
    </div>
    <div class="game-board" id="board">
        <div class="hole" data-index="0"><div class="mole"><div class="nose"></div><div class="mouth"></div><div class="teeth"></div></div></div>
        <div class="hole" data-index="1"><div class="mole"><div class="nose"></div><div class="mouth"></div><div class="teeth"></div></div></div>
        <div class="hole" data-index="2"><div class="mole"><div class="nose"></div><div class="mouth"></div><div class="teeth"></div></div></div>
        <div class="hole" data-index="3"><div class="mole"><div class="nose"></div><div class="mouth"></div><div class="teeth"></div></div></div>
        <div class="hole" data-index="4"><div class="mole"><div class="nose"></div><div class="mouth"></div><div class="teeth"></div></div></div>
        <div class="hole" data-index="5"><div class="mole"><div class="nose"></div><div class="mouth"></div><div class="teeth"></div></div></div>
        <div class="hole" data-index="6"><div class="mole"><div class="nose"></div><div class="mouth"></div><div class="teeth"></div></div></div>
        <div class="hole" data-index="7"><div class="mole"><div class="nose"></div><div class="mouth"></div><div class="teeth"></div></div></div>
        <div class="hole" data-index="8"><div class="mole"><div class="nose"></div><div class="mouth"></div><div class="teeth"></div></div></div>
    </div>
    <button class="btn" id="startBtn">开始游戏</button>

    <div class="overlay hidden" id="overlay">
        <h2>游戏结束!</h2>
        <p>最终得分</p>
        <p class="final-score" id="finalScore">0</p>
        <p class="high-score" id="finalHighScore">最高分: 0</p>
        <button class="btn" id="restartBtn">再玩一次</button>
    </div>

    <div class="combo-display" id="comboDisplay">连击 x2!</div>

    <script>
        const holes = document.querySelectorAll('.hole');
        const moles = document.querySelectorAll('.mole');
        const scoreEl = document.getElementById('score');
        const timeEl = document.getElementById('time');
        const highScoreEl = document.getElementById('highScore');
        const startBtn = document.getElementById('startBtn');
        const overlay = document.getElementById('overlay');
        const finalScoreEl = document.getElementById('finalScore');
        const finalHighScoreEl = document.getElementById('finalHighScore');
        const restartBtn = document.getElementById('restartBtn');
        const comboDisplay = document.getElementById('comboDisplay');

        let score = 0;
        let timeLeft = 30;
        let gameActive = false;
        let moleTimer = null;
        let countdownTimer = null;
        let lastHole = null;
        let combo = 0;
        let comboTimer = null;
        let highScore = parseInt(localStorage.getItem('whackamole_highscore')) || 0;

        highScoreEl.textContent = highScore;

        function randomTime(min, max) {
            return Math.round(Math.random() * (max - min) + min);
        }

        function randomHole() {
            const idx = Math.floor(Math.random() * holes.length);
            const hole = holes[idx];
            if (hole === lastHole) return randomHole();
            lastHole = hole;
            return hole;
        }

        function getDifficultyTime() {
            const elapsed = 30 - timeLeft;
            if (elapsed < 10) return randomTime(700, 1200);
            if (elapsed < 20) return randomTime(500, 900);
            return randomTime(350, 700);
        }

        function peep() {
            const time = getDifficultyTime();
            const hole = randomHole();
            const mole = hole.querySelector('.mole');
            mole.classList.add('up');
            mole.classList.remove('hit');
            moleTimer = setTimeout(() => {
                mole.classList.remove('up');
                if (gameActive) {
                    combo = 0;
                    peep();
                }
            }, time);
        }

        function showCombo() {
            if (combo >= 3) {
                comboDisplay.textContent = `连击 x${combo}!`;
                comboDisplay.classList.add('show');
                clearTimeout(comboTimer);
                comboTimer = setTimeout(() => {
                    comboDisplay.classList.remove('show');
                }, 1000);
            }
        }

        function showScorePopup(hole, points) {
            const popup = document.createElement('div');
            popup.className = 'score-popup';
            popup.textContent = `+${points}`;
            const rect = hole.getBoundingClientRect();
            popup.style.left = rect.left + rect.width / 2 - 15 + 'px';
            popup.style.top = rect.top + 'px';
            document.body.appendChild(popup);
            setTimeout(() => popup.remove(), 800);
        }

        function startGame() {
            score = 0;
            timeLeft = 30;
            combo = 0;
            gameActive = true;
            scoreEl.textContent = score;
            timeEl.textContent = timeLeft;
            startBtn.style.display = 'none';
            overlay.classList.add('hidden');
            moles.forEach(m => {
                m.classList.remove('up', 'hit');
            });
            peep();
            countdownTimer = setInterval(() => {
                timeLeft--;
                timeEl.textContent = timeLeft;
                if (timeLeft <= 0) {
                    endGame();
                }
            }, 1000);
        }

        function endGame() {
            gameActive = false;
            clearInterval(countdownTimer);
            clearTimeout(moleTimer);
            moles.forEach(m => m.classList.remove('up'));

            if (score > highScore) {
                highScore = score;
                localStorage.setItem('whackamole_highscore', highScore);
                highScoreEl.textContent = highScore;
            }

            finalScoreEl.textContent = score;
            finalHighScoreEl.textContent = `最高分: ${highScore}`;
            overlay.classList.remove('hidden');
            startBtn.style.display = 'inline-block';
        }

        function bonk(e) {
            if (!e.isTrusted) return;
            const mole = this.querySelector('.mole');
            if (!mole.classList.contains('up') || mole.classList.contains('hit')) return;

            mole.classList.add('hit');
            mole.classList.remove('up');

            combo++;
            const points = combo >= 5 ? 3 : combo >= 3 ? 2 : 1;
            score += points;
            scoreEl.textContent = score;

            showScorePopup(this, points);
            showCombo();

            clearTimeout(moleTimer);
            if (gameActive) {
                setTimeout(peep, 200);
            }
        }

        holes.forEach(hole => hole.addEventListener('mousedown', bonk));
        holes.forEach(hole => hole.addEventListener('touchstart', (e) => {
            e.preventDefault();
            bonk.call(hole, e);
        }));
        startBtn.addEventListener('click', startGame);
        restartBtn.addEventListener('click', startGame);
    </script>
</body>
</html>
